/* WIMORO — clans module */

'use strict';
/* =====================================================================================
 *  Clans
 *  ------------------------------------------------------------------------------------
 *  - Création dès le rang Argent, compte de plus de 14 jours, 50 $ de frais non remboursables.
 *    Nom, tag de 3-4 lettres affiché partout à côté du pseudo, emblème, langues, catégories,
 *    description. 50 membres maximum.
 *  - Accès : Ouvert (rang minimum), Sur candidature (rang minimum + validation par un
 *    officier), Sur invitation. Rôles : chef, jusqu'à 5 officiers, membres. Chef inactif
 *    30 jours → le clan passe à l'officier le plus actif. Quitter = 7 jours d'attente.
 *  - Classement mensuel : XP de clan = volume misé par les membres sur le mois, plafonné
 *    par membre et par jour ; coefficient de forme = ROI du clan sur le mois, borné entre
 *    ×0,5 et ×2 ; score = XP × coefficient. Seuls les 25 meilleurs contributeurs comptent.
 *    Il faut 15 jours d'ancienneté dans le mois pour compter et être récompensé. Les mises
 *    entre deux membres du même clan sur le même marché ne donnent pas d'XP.
 *  - Divisions : cinq divisions de 20 clans (Division 5 → Division 1), 3 montées et 3 descentes par mois,
 *    cagnotte par division financée par une part des frais générés par ses clans, répartie
 *    au prorata des points. Top 3 mondial : trophée, tag doré un mois, emblème en accueil.
 *  - Guerres de clans : le chef déclare, matchmaking dans la division, 48 h, buy-in par
 *    participant dans la cagnotte de guerre, score = points des 10 meilleurs de chaque camp.
 *  - Vie du clan : chat, fil d'actualité (opt-in), positions du clan, appel de clan,
 *    récap hebdo en image. Pas de trésor : toutes les cagnottes passent par le séquestre.
 *    Les limites de jeu responsable priment sur tout.
 * ===================================================================================== */
const CLAN={FEE:50,MIN_TIER:2,MIN_AGE_D:14,MAX:50,OFFICERS:5,LEAVE_WAIT_D:7,CHIEF_IDLE_D:30,TOP_CONTRIB:25,MIN_DAYS:15,DAY_CAP:2000,WAR_H:48,WAR_BUYIN:20,POT_SHARE:.10,DIVS:['bronze','argent','or','platine','diamant'],DIV_NUM:[5,4,3,2,1],DIV_N:20,DIV_MIN:40,WAR_FEE:.04};
/* noms bruts (clés), traduits à l'affichage par _t ; Array(…) les garde hors du wrapper */
const CL_ADJ=Array('Loups','Faucons','Requins','Taureaux','Renards','Lynx','Aigles','Panthères','Vikings','Pirates','Samouraïs','Titans','Phénix','Cobras','Grizzlys','Dragons','Corbeaux','Lions','Dauphins','Spartiates');
const CL_SUF=Array('{0} du Nord','{0} de Minuit','{0} Dorés','{0} Bleus','{0} de Fer','{0} Rapides','{0} Silencieux','{0} du Volume','{0} de la Bougie','{0} Sans Peur','{0} du Break Even','{0} de Paris','{0} de Tel-Aviv','{0} de Lisbonne','{0} de Montréal','{0} du Delta','{0} de l’Alpha','{0} de la Tendance','{0} du Jeudi','{0} Tout-Terrain');
const clanNameOf=(a,s)=>_t(s,[_t(a)]);
const CL_ICONS=['shield','bolt','flame','crown','star','trophy','target','league','chart','rotate'];
const CL_COLS=['#2448FF','#F59A0B','#12A150','#7350E3','#E11D74','#0E9AA7','#B91C1C','#0F766E','#4338CA','#92400E'];
const CL_LANGS={fr:_t("Français"),en:_t("Anglais"),he:_t("Hébreu"),es:_t("Espagnol"),pt:_t("Portugais")};
/* ---------- Annuaire simulé : 100 clans, 20 par division ---------- */
const CLANS=[],CK={};
{const rr=rng(hash('clans-2026-11'));const cats=CATS.filter(c=>c!=='Tout');const uids=USER_IDS.slice();
 for(let di=0;di<5;di++)for(let k=0;k<20;k++){const i=di*20+k,name=clanNameOf(CL_ADJ[(i*7+di)%CL_ADJ.length],CL_SUF[(i*3+k)%CL_SUF.length]);const tag=(CL_ADJ[(i*7+di)%CL_ADJ.length].slice(0,2)+CL_SUF[(i*3+k)%CL_SUF.length].replace(/^\{0\} /,'').replace(/^(du|de la|de|d’|de l’)\s?/,'').replace(/[^A-Za-zÀ-ÿ]/g,'').slice(0,2)).toUpperCase().replace(/[ÀÂ]/g,'A').replace(/[ÉÈÊ]/g,'E').replace(/Ô/g,'O').replace(/Î/g,'I');
  const n=12+Math.floor(rr()*38),xp=Math.round((40000+rr()*260000)*(1+di*.7)),roi=(rr()-.42)*.6,coef=Math.round(clamp(1+roi,.5,2)*1000)/1000,score=Math.round(xp*coef);
  const c={id:'c'+(i+1),name,tag,emblem:{ic:CL_ICONS[i%CL_ICONS.length],col:CL_COLS[(i*3+di)%CL_COLS.length]},lang:[['fr'],['fr','en'],['en'],['he'],['fr','he'],['es'],['pt','en']][i%7],cats:[cats[i%cats.length],cats[(i*5+2)%cats.length]].filter((x,j,a)=>a.indexOf(x)===j),desc:`${_t("{0} : on joue {1} surtout, et on partage nos lectures de marché chaque soir.",[name,_t(cats[i%cats.length]).toLowerCase()])}`,access:['open','apply','invite'][i%3],minRank:Math.min(7,di+ (i%2)),chief:uids[i%uids.length],officers:uids.filter((u,j)=>j!==i%uids.length).slice(0,2+(i%3)),n,div:CLAN.DIVS[di],xp,roi,coef,score,createdAt:now()-(60+Math.floor(rr()*400))*86400e3,members:[],war:null,calls:[],feed:[],wars:[]};
  CLANS.push(c);CK[c.id]=c;}
 /* classement dans chaque division */
 for(const dv of CLAN.DIVS){const L=CLANS.filter(c=>c.div===dv).sort((a,b)=>b.score-a.score);L.forEach((c,i)=>c.rank=i+1);}
 /* joueurs simulés : la plupart ont un clan (les mêmes 10 joueurs reviennent dans plusieurs clans de démo) */
 USER_IDS.forEach((u,i)=>{if(i%5===4)return;const c=CLANS[(hash(u)%40)+60];c.members.push({u,since:now()-(20+hash(u)%200)*86400e3,pts:Math.round(1000+hash(u+'p')%9000)});userOf(u).clan=c.id;});
}
/* ---------- Mon clan ---------- */
const myClan=()=>S.me.clan&&CK[S.me.clan.id]?CK[S.me.clan.id]:null;
const clanOf=u=>u==='me'?myClan():(USERS[u]&&userOf(u).clan?CK[userOf(u).clan]:null);
const clanRole=()=>S.me.clan?S.me.clan.role:'';
const isOfficer=()=>['chef','officier'].includes(clanRole());
const clanMembersN=c=>c.n+(c.members.length?0:0)+(myClan()===c?1:0);
const clanSince=c=>S.me.clan&&S.me.clan.id===c.id?S.me.clan.since:0;
const accountAgeD=()=>Math.floor((now()-(S.me.createdAt||now()))/86400e3);
/* tag de clan à côté d'un pseudo (doré pour le top 3 mondial) */
function tagH(u,inl){const c=clanOf(u);if(!c)return '';const g=clanWorldRank(c)<=3?' gold':'';return inl?`<span class="ctg${g}" data-tip="${esc(c.name)}" data-href="#clan-${c.id}">${esc(c.tag)}</span>`:`<a class="ctg${g}" href="#clan-${c.id}" data-tip="${esc(c.name)}" aria-label="${esc(_t('Clan {0}',[c.name]))}">${esc(c.tag)}</a>`;}
/* C8 : le nom du clan apparaît en bulle au survol du tag (souris) ou au premier toucher ; le clic, ou un toucher sur la bulle, ouvre la page du clan */
let CTIP=null,CTIP_PT='mouse',CTIP_T=0,CTIP_W=0;
function ctipHide(){clearTimeout(CTIP_T);clearInterval(CTIP_W);if(CTIP){CTIP.t.remove();CTIP=null;}}
function ctipShow(a,touch){ctipHide();const t=document.createElement('a');t.className='ctip'+(touch?' tch':'');t.href=a.getAttribute('href')||a.dataset.href;t.textContent=a.dataset.tip;document.body.appendChild(t);
 const r=a.getBoundingClientRect(),w=t.offsetWidth,h=t.offsetHeight,vw=document.documentElement.clientWidth;t.style.left=clamp(r.left+r.width/2-w/2,8,Math.max(8,vw-w-8))+'px';t.style.top=(r.top-h-7<4?r.bottom+7:r.top-h-7)+'px';CTIP={a,t,x:r.left,y:r.top};if(touch)CTIP_T=setTimeout(ctipHide,4500);else CTIP_W=setInterval(()=>{if(!CTIP||!document.contains(CTIP.a)||!CTIP.a.matches(':hover'))ctipHide();},700);}
document.addEventListener('pointerdown',e=>{CTIP_PT=e.pointerType||'mouse';},true);
document.addEventListener('pointerover',e=>{if(e.pointerType!=='mouse')return;const a=e.target.closest?e.target.closest('.ctg[data-tip]'):null;if(a){if(!CTIP||CTIP.a!==a)ctipShow(a,false);}else if(CTIP)ctipHide();},{passive:true});
document.addEventListener('click',e=>{if(e.target.closest&&e.target.closest('.ctip')){setTimeout(ctipHide,0);return;}const a=e.target.closest?e.target.closest('.ctg[data-tip]'):null;
 if(a&&CTIP_PT!=='mouse'&&(!CTIP||CTIP.a!==a)){e.preventDefault();e.stopPropagation();ctipShow(a,true);return;}ctipHide();},true);
addEventListener('scroll',()=>{if(!CTIP)return;const r=CTIP.a.getBoundingClientRect();if(!document.contains(CTIP.a)||Math.abs(r.left-CTIP.x)>3||Math.abs(r.top-CTIP.y)>3)ctipHide();},{passive:true,capture:true});addEventListener('hashchange',ctipHide);
/* Moins de 40 clans : un seul classement mondial, top 3 récompensé chaque mois. À partir de 40 : divisions de 20.
 * Démo : S.me.clanSim = 'many' (100 clans simulés) ou 'few' (12 clans) pour voir les deux affichages. */
const CL_FEW=['c4','c8','c25','c30','c1','c21','c41','c61','c81','c15','c70'];
const clanSim=()=>S.me.clanSim==='few'?'few':'many';
function clansActive(){if(clanSim()==='many')return CLANS;const mine=myClan();return CLANS.filter(c=>c.mine||CL_FEW.includes(c.id)||c===mine);}
const clanDivMode=()=>clansActive().length>=CLAN.DIV_MIN;
const clansSorted=()=>clansActive().slice().sort((a,b)=>b.score-a.score);
function clanWorldRank(c){return clansSorted().indexOf(c)+1;}
/* libellé de position : « Division 3, 12e sur 20 » ou « 3e sur 12 clans » */
function clanPosTxt(c){return clanDivMode()?`${_t("{0}, {1} sur {2}",[divName(c),ordinal(c.rank),CLAN.DIV_N])}`:_t('{0} sur {1} clans',[ordinal(clanWorldRank(c)),clansActive().length]);}
const worldPot=()=>Math.round(clansActive().reduce((t,c)=>t+c.xp,0)*.02*CLAN.POT_SHARE);
function emblemH(c,size=28){return `<span class="cemb${c.emblem.col==='#F59A0B'?' cemb-clair':''}" style="background:${c.emblem.col};width:${size}px;height:${size}px">${ic(c.emblem.ic,Math.round(size*.55),'#fff',2.2)}</span>`;}
const divNameI=i=>_t('Division {0}',[CLAN.DIV_NUM[i]]);const divName=c=>divNameI(CLAN.DIVS.indexOf(c.div));
const divPot=dv=>{const L=CLANS.filter(c=>c.div===dv);return Math.round(L.reduce((t,c)=>t+c.xp,0)*.02*CLAN.POT_SHARE);};
const monthLeft=()=>{const d=new Date();return Math.max(1,new Date(d.getFullYear(),d.getMonth()+1,1).getDate()-d.getDate()+1);};
/* ---------- Contribution : volume misé, plafonné par jour, mises entre membres exclues ---------- */
const clanVolToday=()=>{const v=S.me.clanVol||{};return v[today()]||0;};
function clanRecordBet(mid,amt){const c=myClan();if(!c||!amt||SRV())return;S.me.clanVol=S.me.clanVol||{};const mates=clanMates(c);if(mid&&mates.some(u=>playerBets(u).some(b=>b.m.id===mid))){S.me.clanSkipped=(S.me.clanSkipped||0)+1;return;}
 const d=today(),cur=S.me.clanVol[d]||0,add=Math.max(0,Math.min(CLAN.DAY_CAP-cur,amt));S.me.clanVol[d]=cur+add;S.me.clanXP=(S.me.clanXP||0)+add;if(S.me.prefs&&S.me.prefs.clanFeed!==false&&mid&&MK[mid])clanFeedPush(c,{u:'me',txt:`${_t("{0} vient de miser {1} sur {2}.",[S.me.n,F.usd0(amt),MK[mid].short])}`});save();}
const clanMates=c=>c.members.map(m=>m.u);
/* code d'invitation WMR-XXXX, stable par clan */
function clanCode(c){if(c.code)return c.code;                      /* clan créé par un joueur : son code vient du serveur */
 const r=rng(hash('clan-code-'+c.id)),al='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';return 'WMR-'+Array.from({length:4},()=>al[Math.floor(r()*al.length)]).join('');}
const clanByCode=code=>CLANS.find(c=>clanCode(c)===code)||null;
function clanFeedPush(c,e){c.feed.unshift(Object.assign({at:now()},e));c.feed=c.feed.slice(0,30);}
/* points d'un membre pour le mois : contribution plafonnée × ancienneté suffisante */
const memberCounts=(c,since)=>(now()-since)/86400e3>=CLAN.MIN_DAYS;
/* ---------- Création / accès ---------- */
function clanCanCreate(){const r=myRank();if(myClan())return _t("Tu es déjà dans un clan.");if(r.t<CLAN.MIN_TIER)return `${_t("Il faut le rang {0} pour créer un clan.",[rankName(CLAN.MIN_TIER,0)])}`;if(accountAgeD()<CLAN.MIN_AGE_D)return `${_t("Ton compte doit avoir plus de {0} jours ({1} aujourd’hui).",[CLAN.MIN_AGE_D,accountAgeD()])}`;if(S.me.balance<CLAN.FEE)return `${_t("Il faut {0} de frais de création.",[F.usd0(CLAN.FEE)])}`;return '';}
function clanLeaveWait(){if(!S.me.clanLeftAt)return 0;return Math.max(0,S.me.clanLeftAt+CLAN.LEAVE_WAIT_D*86400e3-now());}
function clanCreate(f){const why=clanCanCreate();if(why){toast({tone:'amber',icon:'lock',title:_t("Création impossible"),text:why});return null;}
 const name=f.name.trim(),tag=f.tag.trim().toUpperCase();if(name.length<3||name.length>28){toast({tone:'amber',icon:'info',title:_t("Nom invalide"),text:_t("3 à 28 caractères.")});return null;}if(!/^[A-Z0-9]{3,4}$/.test(tag)){toast({tone:'amber',icon:'info',title:_t("Tag invalide"),text:_t('3 ou 4 lettres ou chiffres.')});return null;}if(CLANS.some(c=>c.tag===tag)){toast({tone:'amber',icon:'info',title:_t("Tag déjà pris"),text:_t("Choisis un autre tag.")});return null;}
 if(SRV()){srvClanCreer(f,name,tag);return null;}               /* mode Compte : frais, unicité du tag et appartenance tenus par le serveur */
 S.me.balance-=CLAN.FEE;S.me.realized-=CLAN.FEE;const c={id:'me-'+now().toString(36),name,tag,emblem:{ic:f.ic||'shield',col:f.col||'#2448FF'},lang:f.lang.length?f.lang:['fr'],cats:f.cats,desc:f.desc.trim(),access:f.access,minRank:+f.minRank||0,chief:'me',officers:[],n:0,div:'bronze',xp:0,roi:0,coef:1,score:0,createdAt:now(),members:[],war:null,calls:[],feed:[],wars:[],rank:20,mine:true};
 CLANS.push(c);CK[c.id]=c;S.me.clan={id:c.id,role:'chef',since:now()};S.me.clanVol={};S.me.clanXP=0;S.me.clanCreated=(S.me.clanCreated||[]).concat([{id:c.id,name,tag,at:now()}]);clanFeedPush(c,{u:'me',txt:`${_t("{0} a fondé le clan.",[S.me.n])}`});
 const r=room('clan:'+c.id);r.name=name;r.kind='clan';save();updateHeader();notif('shield',`${_t("Clan {0} [{1}] créé. {2} de frais, non remboursables.",[name,tag,F.usd0(CLAN.FEE)])}`,'#clan-'+c.id);return c;}
function clanJoin(c,viaApp,viaCode){if(myClan()){toast({tone:'amber',icon:'info',title:_t("Tu as déjà un clan"),text:_t("Quitte-le d’abord.")});return false;}const w=clanLeaveWait();if(w>0){toast({tone:'amber',icon:'lock',title:_t("Attends encore un peu"),text:`${_t("Tu as quitté un clan il y a moins de {0} jours : encore {1} jour{2}.",[CLAN.LEAVE_WAIT_D,Math.ceil(w/86400e3),Math.ceil(w/86400e3)>1?'s':''])}`});return false;}
 if(clanMembersN(c)>=CLAN.MAX){toast({tone:'amber',icon:'info',title:_t("Clan complet"),text:`${_t("{0} membres maximum.",[CLAN.MAX])}`});return false;}
 if(myRank().t<c.minRank){toast({tone:'amber',icon:'lock',title:_t("Rang insuffisant"),text:`${_t("Ce clan demande au moins le rang {0}.",[rankName(c.minRank,0)])}`});return false;}
 if(SRV()){srvClanRejoindre(c,viaCode);return false;}
 S.me.clan={id:c.id,role:'membre',since:now()};S.me.clanVol={};S.me.clanXP=0;c.n++;clanFeedPush(c,{u:'me',txt:`${_t("{0} a rejoint le clan.",[S.me.n])}`});addMsg('clan:'+c.id,mkMsg({k:'evt',text:`${_t("{0} rejoint {1}.",[S.me.n,c.name])}`}));save();updateHeader();
 toast({tone:'green',icon:'shield',force:true,title:`${_t("Bienvenue chez {0} [{1}]",[c.name,c.tag])}`,text:viaApp?_t("Ta candidature a été acceptée par un officier."):_t("Ton tag apparaît désormais à côté de ton pseudo."),href:'#clan-'+c.id});notif('shield',`${_t("Tu as rejoint le clan {0} [{1}].",[c.name,c.tag])}`,'#clan-'+c.id);return true;}
function clanApply(c){if(myClan())return;S.me.clanApps=S.me.clanApps||{};if(S.me.clanApps[c.id])return;if(SRV()){srvClanCandidater(c);return;}S.me.clanApps[c.id]=now();save();toast({tone:'blue',icon:'send',title:_t("Candidature envoyée"),text:`${_t("Un officier de {0} doit la valider.",[c.name])}`});const ep=S.epoch;setTimeout(()=>{if(ep!==S.epoch||!S.me.clanApps||!S.me.clanApps[c.id])return;delete S.me.clanApps[c.id];if(R()<.8){clanJoin(c,true);if((S.ui.route||'').startsWith('clan'))render(false);}else{notif('shield',`${_t("{0} a refusé ta candidature.",[c.name])}`,'#clans');toast({tone:'amber',icon:'info',title:_t("Candidature refusée"),text:`${_t("{0} n’a pas retenu ta candidature cette fois.",[c.name])}`});}},8000+R()*10000);}
function clanLeave(){const c=myClan();if(!c)return;if(SRV()){srvClanQuitter(c);return;}if(c.chief==='me'&&c.n>0&&c.officers.length){c.chief=c.officers[0];c.officers.shift();}
 clanFeedPush(c,{u:'me',txt:`${_t("{0} a quitté le clan.",[S.me.n])}`});c.n=Math.max(0,c.n-(c.mine?0:1));S.me.clan=null;S.me.clanLeftAt=now();S.me.clanVol={};save();updateHeader();toast({icon:'info',force:true,title:`${_t("Tu as quitté {0}",[c.name])}`,text:`${_t("Tu pourras rejoindre un autre clan dans {0} jours.",[CLAN.LEAVE_WAIT_D])}`});}
/* chef inactif 30 jours : le clan passe à l'officier le plus actif (simulé sur les clans de démo) */
function clanChiefCheck(c){if(!c.chiefLastActive)return;if(now()-c.chiefLastActive>CLAN.CHIEF_IDLE_D*86400e3&&c.officers.length){const old=c.chief;c.chief=c.officers[0];c.officers.shift();clanFeedPush(c,{u:c.chief,txt:`${_t("{0} étant inactif depuis 30 jours, {1} devient chef du clan.",[duelUserN(old),duelUserN(c.chief)])}`});c.chiefLastActive=now();}}
/* ---------- Appel de clan ---------- */
function clanCall(c,mid,side){if(!isOfficer())return;const m=MK[mid];if(!m)return;c.calls.unshift({id:'k'+now().toString(36),m:mid,s:side,by:'me',at:now(),followers:[]});c.calls=c.calls.slice(0,6);clanFeedPush(c,{u:'me',txt:`${_t("Appel de clan : {0} épingle {1} côté {2}.",[S.me.n,m.short,side==='oui'?_t("Oui"):_t("Non")])}`});addMsg('clan:'+c.id,mkMsg({k:'evt',text:`${_t("Appel de clan : {0}, côté {1}. Chacun suit avec sa mise, dans ses limites.",[m.short,side==='oui'?_t("Oui"):_t("Non")])}`}));save();
 const ep=S.epoch,call=c.calls[0];setTimeout(()=>{if(ep!==S.epoch)return;call.followers=clanMates(c).slice(0,2+Math.floor(R()*4));notif('users',`${_t("{0} membres ont suivi ton appel de clan sur {1}.",[call.followers.length,m.short])}`,'#clan-'+c.id);if((S.ui.route||'').startsWith('clan'))render(false);},5000+R()*8000);}
/* ---------- Guerres de clans ---------- */
function clanWarDeclare(c){if(clanRole()!=='chef'||c.war)return;const foes=(clanDivMode()?clansActive().filter(x=>x.div===c.div):clansActive()).filter(x=>x!==c);const foe=pick(foes);c.war={id:'w'+now().toString(36),foe:foe.id,at:now(),endAt:now()+CLAN.WAR_H*3600e3,pot:0,mine:[],theirs:(clanMates(foe).length?clanMates(foe):Array.from({length:10},(_,i)=>foe.tag.toLowerCase()+'_'+(i+1))).slice(0,10).map(u=>({u,pts:Math.round(200+R()*900)})),status:'live',buyin:CLAN.WAR_BUYIN};
 c.war.pot=c.war.theirs.length*CLAN.WAR_BUYIN;clanFeedPush(c,{u:'me',txt:`${_t("Guerre déclarée contre {0} [{1}] : 48 h, buy-in {2} par participant.",[foe.name,foe.tag,F.usd0(CLAN.WAR_BUYIN)])}`});addMsg('clan:'+c.id,mkMsg({k:'evt',text:`${_t("Guerre de clans contre {0} [{1}] : 48 h pour marquer des points. Buy-in {2}.",[foe.name,foe.tag,F.usd0(CLAN.WAR_BUYIN)])}`}));save();
 const ep=S.epoch;setTimeout(()=>{if(ep!==S.epoch||!c.war)return;clanMates(c).slice(0,3+Math.floor(R()*5)).forEach(u=>{if(!c.war.mine.some(x=>x.u===u)){c.war.mine.push({u,pts:Math.round(150+R()*800)});c.war.pot+=CLAN.WAR_BUYIN;}});if((S.ui.route||'').startsWith('clan'))render(false);},4000);}
function clanWarJoin(c){const w=c.war;if(!w||w.status!=='live'||w.mine.some(x=>x.u==='me'))return;if(typeof rgBlocked==='function'&&rgBlocked('bet'))return;if(w.buyin>S.me.balance){toast({tone:'amber',icon:'wallet',title:_t("Solde insuffisant"),text:_t("Dépose des fonds pour continuer."),href:'#depot'});return;}
 S.me.balance-=w.buyin;w.pot+=w.buyin;w.mine.push({u:'me',pts:Math.round(S.me.clanXP||0)/10,paid:w.buyin});save();updateHeader();toast({tone:'blue',icon:'shield',force:true,title:_t("Tu participes à la guerre"),text:`${_t("{0} dans la cagnotte de guerre (séquestre Wimoro). Tes points suivent tes mises pendant 48 h.",[F.usd0(w.buyin)])}`});}
function clanWarTick(){const c=myClan();if(!c||!c.war||c.war.status!=='live')return;const w=c.war,rr=rng(hash(w.id+Math.floor(now()/60000)));for(const p of w.mine)if(p.u!=='me')p.pts+=Math.round(rr()*25);for(const p of w.theirs)p.pts+=Math.round(rr()*25);const me=w.mine.find(x=>x.u==='me');if(me)me.pts=Math.round((S.me.clanXP||0)/10);
 if(now()>=w.endAt){const sc=L=>L.slice().sort((a,b)=>b.pts-a.pts).slice(0,10).reduce((t,x)=>t+x.pts,0);const a=sc(w.mine),b=sc(w.theirs);w.status=a>b?'won':a<b?'lost':'draw';w.endAt=now();const foe=CK[w.foe];
  if(w.status==='won'&&me){const share=w.pot*(1-CLAN.WAR_FEE)/Math.max(1,w.mine.length);S.me.balance+=share;S.me.realized+=share-me.paid;gainXP(50);toast({tone:'green',icon:'trophy',force:true,title:`${_t("Guerre gagnée contre {0}",[foe.name])}`,text:`${_t("+{0} pour toi, cagnotte {1} partagée entre les participants.",[F.usd(share-me.paid),F.usd0(w.pot)])}`,href:'#clan-'+c.id});}
  else if(w.status==='draw'&&me){S.me.balance+=me.paid;}
  else if(me){S.me.realized-=me.paid;toast({tone:'red',icon:'shield',force:true,title:`${_t("Guerre perdue contre {0}",[foe.name])}`,text:`${_t("{0} points contre {1}. La cagnotte va aux vainqueurs.",[a,b])}`,href:'#clan-'+c.id});}
  c.wars.unshift({foe:w.foe,at:w.endAt,status:w.status,a,b,pot:w.pot});c.war=null;save();if((S.ui.route||'').startsWith('clan'))render(false);}}
/* ---------- Récap hebdo en image ---------- */
function clanCanvas(c){const cv=document.createElement('canvas'),W=1080,H=1350;cv.width=W;cv.height=H;const ctx=cv.getContext('2d');const P=imgPal(),sg=plain(cssVar('--sg')),font=(w,z)=>`${w} ${z}px ${sg}`;ctx.fillStyle=P.bg;ctx.fillRect(0,0,W,H);
 ctx.direction=RTL?'rtl':'ltr';const X=RTL?W-80:80;ctx.textAlign=RTL?'right':'left';const txt=z=>plain(String(z));ctx.font=font(600,54);ctx.fillStyle=P.text;ctx.fillText('wimoro',X+(RTL?-70:70),130);drawLogo(ctx,RTL?W-80-56:80,84,56);
 ctx.fillStyle=c.emblem.col;rrect(ctx,RTL?W-80-32:80,212,32,32,8);ctx.fill();ctx.font=font(500,34);ctx.fillStyle=P.text3;ctx.fillText(txt(_t("Récap de la semaine du clan")),X+(RTL?-48:48),240);ctx.font=font(600,84);ctx.fillStyle=P.text;ctx.fillText(txt(`${c.name} [${c.tag}]`),X,330);
 const rows=[clanDivMode()?[divName(c),`${_t("{0} sur {1}",[ordinal(c.rank),CLAN.DIV_N])}`]:[_t("Classement mondial"),_t('{0} sur {1} clans',[ordinal(clanWorldRank(c)),clansActive().length])],[_t("Score du mois"),F.int(c.score)],[_t("XP de clan"),F.int(c.xp)],[_t("Coefficient de forme"),`${clanCoef(c)}`],[_t("Membres"),String(clanMembersN(c))],[_t("Guerres gagnées"),String(c.wars.filter(w=>w.status==='won').length)]];let y=440;for(const [k,v] of rows){ctx.font=font(500,32);ctx.fillStyle=P.text3;ctx.fillText(txt(k),X,y);ctx.font=font(600,44);ctx.fillStyle=P.text;ctx.direction='ltr';ctx.textAlign=RTL?'left':'right';ctx.fillText(txt(v),RTL?80:W-80,y);ctx.direction=RTL?'rtl':'ltr';ctx.textAlign=RTL?'right':'left';y+=86;}
 y=H-250;ctx.strokeStyle=P.line;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(80,y-40);ctx.lineTo(W-80,y-40);ctx.stroke();ctx.font=font(600,34);ctx.fillStyle=P.text;ctx.fillText(txt(`${_t("Top contributeur : {0}",[duelUserN(c.chief)])}`),X,y+10);ctx.font=font(500,28);ctx.fillStyle=P.text2;ctx.fillText(txt(c.access==='open'?`${_t("Clan ouvert dès le rang {0}",[rankName(c.minRank,0)])}`:c.access==='apply'?_t("Sur candidature"):_t("Sur invitation")),X,y+62);ctx.font=font(600,30);ctx.fillStyle=P.accent;ctx.fillText('wimoro.com',X,y+118);return cv;}
async function clanShare(c){try{if(document.fonts&&document.fonts.ready)await document.fonts.ready;}catch(e){}const url=clanCanvas(c).toDataURL('image/png');S.ui.shareImg=url;S.ui.shareTxt=`${_t("{0} [{1}] sur Wimoro : {2}. Rejoins-nous avec le code {3} : {4}",[c.name,c.tag,clanPosTxt(c),clanCode(c),refLink()])}`;
 openModal(`<div class="md shm"><div class="md-h"><div><p>${_t("Clan")}</p><h3>${_t("Récap hebdo en image")}</h3></div><button class="x" data-a="close" aria-label="${_t("Fermer")}">${ic('x')}</button></div><img class="shimg" src="${url}" alt="${_t("Récap du clan")}"><div class="cpm-acts"><button class="btn b-ink lg" data-a="share-send">${_t("{0} Partager l’image",[ic('share',16,'#fff')])}</button><button type="button" class="btn b-white lg" data-a="share-save" data-name="wimoro-clan.png">${_t("{0} Enregistrer l’image",[ic('down',16)])}</button></div></div>`,'wide');}
/* ---------- Semaine : classement interne au clan (meilleur profit depuis lundi) ---------- */
const weekKey=t=>{const d=new Date(t);const day=(d.getDay()+6)%7;d.setHours(0,0,0,0);d.setDate(d.getDate()-day);return d.getTime();};
const weekEnd=()=>weekKey(now())+7*86400e3;
function clanWeekRows(c,wk){wk=wk||weekKey(now());const ids=[...(myClan()===c?['me']:[]),...clanMates(c)];return ids.map(u=>{if(u==='me'){const h=S.me.history.filter(x=>x.at>=wk&&x.at<wk+7*86400e3);return {u,profit:h.reduce((t,x)=>t+(x.pnl||0),0),bets:h.length,acc:stats().acc};}const U=userOf(u),r=rng(hash(c.id+u+wk));return {u,profit:Math.round(U.profit*.02*(.3+r()*1.2))*(r()<.15?-1:1),bets:Math.round(6+r()*40),acc:U.acc};}).sort((a,b)=>b.profit-a.profit);}
function clanWeekH(c){const rows=clanWeekRows(c),mine=myClan()===c,me=rows.findIndex(x=>x.u==='me'),left=weekEnd()-now(),dh=_t('{0} j {1} h',[Math.floor(left/86400e3),Math.floor(left%86400e3/3600e3)]);
 return `<div class="clweek"><div class="ph"><div><div class="h2">${_t("Classement de la semaine")}</div><div class="sub">${_t("Profit réalisé depuis lundi, entre membres du clan. Le premier dimanche soir gagne 300 XP et le badge Champion de clan.")}</div></div><span class="xpc">${_t("Fin dans {0}",[dh])}</span></div>
 <section class="pn lb clip mt-3"><div class="lh"><span>#</span><span>${_t("Joueur")}</span><span>${_t("Rang")}</span><span class="r">${_t("Profit")}</span><span class="r">${_t("Précision")}</span><span class="r">${_t("Paris")}</span><span></span></div>${rows.map((x,i)=>lrH(x,i+1)).join('')}</section>
 ${mine?(me===0?`<p class="plead t-3 mt-3">${_t("Tu es en tête. Garde ta place jusqu’à dimanche.")}</p>`:`<p class="plead t-3 mt-3">${_t("Tu es {0}, à {1} du premier.",[ordinal(me+1),F.usd0(Math.max(0,rows[0].profit-rows[me].profit))])}</p><div class="hbtns mt-3"><a class="btn b-pri" href="#eclair">${_t("{0} Jouer l’éclair",[ic('bolt',16,'#fff')])}</a><a class="btn b-white" href="#accueil">${_t("Voir les marchés")}</a></div>`):''}</div>`;}
/* fin de semaine : le premier du clan gagne 300 XP et le badge */
function clanWeekAward(){const c=myClan();if(!c)return;const prev=weekKey(now())-7*86400e3;if(S.me.clanWeekDone===prev)return;S.me.clanWeekDone=prev;if(clanSince(c)>prev+7*86400e3)return;const rows=clanWeekRows(c,prev);if(rows.length>1&&rows[0].u==='me'&&rows[0].profit>0){S.me.weekChamp=(S.me.weekChamp||0)+1;gainXP(300);notif('trophy',`${_t("Champion de la semaine chez {0} : +300 XP.",[c.name])}`,'#clan-'+c.id);checkBadges();}save();}
/* ---------- Pages ---------- */
function clanRowH(c,i){const mine=myClan()===c;return `<a class="clrow${mine?' mine':''}" href="#clan-${c.id}">${emblemH(c,36)}<span class="cln"><b>${esc(c.name)} <span class="ctg${clanWorldRank(c)<=3?' gold':''}">${esc(c.tag)}</span></b><small><span>${clanDivMode()?`${divName(c)} · ${ordinal(c.rank)}`:ordinal(clanWorldRank(c))} · ${_t('{0} membres',[clanMembersN(c)])}</span><span class="cl2">${c.lang.map(l=>CL_LANGS[l]||l).join(', ')} · ${c.cats.map(x=>_t(x)).join(', ')}</span></small></span><span class="clsc"><span class="clsc-k">${_t("Score")}</span><b class="num">${F.int(c.score)}</b><small><span>${c.access==='open'?_t("Ouvert"):c.access==='apply'?_t("Candidature"):_t("Invitation")}</span>${c.minRank?`<span class="cl2">${rankName(c.minRank,0)}+</span>`:''}</small></span></a>`;}
/* Annuaire sur ordinateur (880 px et plus) : un tableau. Le rang mondial, le clan et son tag (jamais coupé), la division
   et la place dans la division, les membres, l'accès, les langues, les catégories, le score ; les colonnes s'ajoutent
   selon la largeur du tableau (css/screens.css, section communaute). Sur téléphone, la liste clanRowH ne change pas. */
const clanAccTxt=c=>c.access==='open'?_t("Ouvert"):c.access==='apply'?_t("Candidature"):_t("Invitation");
function clanTabH(L){const DM=clanDivMode();
 return `<div class="cltab${DM?'':' nodiv'}"><div class="clt-h" aria-hidden="true"><span class="r">#</span><span>${_t("Clan")}</span><span class="clt-dv">${_t("Division")}</span><span class="r">${_t("Membres")}</span><span>${_t("Accès")}</span><span>${_t("Langues")}</span><span>${_t("Catégories")}</span><span class="r">${_t("Score")}</span></div>
 ${L.map(c=>`<a class="clt-r${myClan()===c?' mine':''}" href="#clan-${c.id}"><span class="num r clt-i">${F.int(clanWorldRank(c))}</span><span class="clt-n">${emblemH(c,32)}<span class="hub-nm">${esc(c.name)}</span><span class="ctg${clanWorldRank(c)<=3?' gold':''}">${esc(c.tag)}</span></span><span class="clt-dv">${DM?`${divName(c)}<small>${_t("{0} sur {1}",[ordinal(c.rank),CLAN.DIV_N])}</small>`:''}</span><span class="r num">${F.int(clanMembersN(c))}</span><span>${clanAccTxt(c)}${c.minRank?`<small>${rankName(c.minRank,0)}+</small>`:''}</span><span class="clt-x">${c.lang.map(l=>CL_LANGS[l]||l).join(', ')}</span><span class="clt-x">${c.cats.map(x=>_t(x)).join(', ')}</span><span class="r num"><b>${F.int(c.score)}</b></span></a>`).join('')}</div>`;}
/* le bouton qui fait entrer dans un clan : rejoindre (ouvert), candidater (sur candidature) ; rien pour un clan sur invitation */
function clanEntrerH(c,cls){if(!c||myClan()||c.access==='invite')return '';if(c.access==='apply')return S.me.clanApps&&S.me.clanApps[c.id]?`<span class="btn b-ghost" disabled>${_t("Candidature envoyée")}</span>`:`<button class="btn ${cls}" data-a="cl-apply" data-id="${c.id}">${_t("{0} Candidater",[ic('send',16,'#fff')])}</button>`;
 return `<button class="btn ${cls}" data-a="cl-join" data-id="${c.id}">${_t("{0} Rejoindre",[ic('shield',16,'#fff')])}</button>`;}
function clanRecommended(){const r=myRank(),mine=S.me.interests||[];return clansActive().filter(c=>c.access!=='invite'&&c.minRank<=r.t&&clanMembersN(c)<CLAN.MAX&&c!==myClan()).sort((a,b)=>(b.cats.filter(x=>mine.includes(x)).length-a.cats.filter(x=>mine.includes(x)).length)||Math.abs(a.minRank-r.t)-Math.abs(b.minRank-r.t)||b.score-a.score)[0];}
function vClans(){const f=S.ui.clf||(S.ui.clf={div:'',lang:'',cat:'',tab:'annuaire'});const mine=myClan(),rec=clanRecommended(),why=clanCanCreate();
 const DM=clanDivMode();let L=clansActive().filter(c=>(!DM||!f.div||c.div===f.div)&&(!f.lang||c.lang.includes(f.lang))&&(!f.cat||c.cats.includes(f.cat))).sort((a,b)=>b.score-a.score);
 const tabs=`<div class="tabs utabs">${[['annuaire',_t("Annuaire")],['classement',_t("Classement du mois")],['regles',_t("Règles")]].map(([k,l])=>`<button class="${f.tab===k?'on':''}" data-a="cl-tab" data-v="${k}">${l}</button>`).join('')}</div>`;
 let body='';
 if(f.tab==='annuaire')body=`<div class="clfilters">${DM?`<label class="sort">${_t("Division")} <select data-clf="div"><option value="">${_t("Toutes")}</option>${CLAN.DIVS.map((d,i)=>`<option value="${d}"${f.div===d?' selected':''}>${divNameI(i)}</option>`).join('')}</select></label>`:''}<label class="sort">${_t("Langue")} <select data-clf="lang"><option value="">${_t("Toutes")}</option>${Object.keys(CL_LANGS).map(l=>`<option value="${l}"${f.lang===l?' selected':''}>${CL_LANGS[l]}</option>`).join('')}</select></label><label class="sort">${_t("Catégorie")} <select data-clf="cat"><option value="">${_t("Toutes")}</option>${CATS.filter(c=>c!=='Tout').map(c=>`<option value="${c}"${f.cat===c?' selected':''}>${_t(c)}</option>`).join('')}</select></label></div>${GRAND()?clanTabH(L.slice(0,40)):`<div class="cllist">${L.slice(0,40).map(clanRowH).join('')}`}${L.length>40?`<p class="sub" style="padding:10px 0 0">${_t("{0} autres clans. Affine les filtres.",[L.length-40])}</p>`:''}${GRAND()?'':'</div>'}`;
 else if(f.tab==='classement'){const trH=(L)=>`<div class="cltable"><div class="cltr h"><span>#</span><span>${_t("Clan")}</span><span class="r">XP</span><span class="r">${_t("Coef.")}</span><span class="r">${_t("Score")}</span></div>${L.map((c,i)=>`<a class="cltr${DM?(i<3?' cl-up':i>=CLAN.DIV_N-3?' cl-down':''):(i<3?' cl-up':'')}${myClan()===c?' mine':''}" href="#clan-${c.id}"><span>${i+1}${DM?(i<3?ic('up',14):i>=CLAN.DIV_N-3?ic('down',14):''):(i<3?ic('trophy',14):'')}</span><span>${emblemH(c,22)} <span class="hub-nm">${esc(c.name)}</span> <span class="ctg${clanWorldRank(c)<=3?' gold':''}">${esc(c.tag)}</span></span><span class="r num">${F.int(c.xp)}</span><span class="r num">${clanCoef(c)}</span><span class="r num"><b>${F.int(c.score)}</b></span></a>`).join('')}</div>`;
  if(DM){const dv=f.div||'or';const D=clansActive().filter(c=>c.div===dv).sort((a,b)=>b.score-a.score);body=`<div class="chips mb-3">${CLAN.DIVS.slice().reverse().map((d)=>`<button class="chip${dv===d?' on':''}" data-a="cl-div" data-v="${d}">${divNameI(CLAN.DIVS.indexOf(d))}</button>`).join('')}</div><p class="sub">${_t("Fin du mois dans {0} jour{1}. Les 3 premiers montent, les 3 derniers descendent. Cagnotte de la division : <b>{2}</b>, financée par {3} des frais générés par ses clans ce mois, répartie entre les membres au prorata de leurs points.",[monthLeft(),monthLeft()>1?'s':'',F.usd0(divPot(dv)),F.pct(CLAN.POT_SHARE*100)])}</p>${trH(D)}<div class="h2 mt-5">${_t("Top 3 mondial")}</div><p class="sub">${_t("Trophée, tag doré pendant un mois, emblème en page d’accueil et cadres d’emblème exclusifs.")}</p>${clansSorted().slice(0,3).map((c,i)=>`<a class="clrow" href="#clan-${c.id}">${emblemH(c,36)}<span class="cln"><b>${i+1}. ${esc(c.name)} <span class="ctg gold">${esc(c.tag)}</span></b><small>${_t("{0} · {1} points",[divName(c),F.int(c.score)])}</small></span>${ic('trophy',20,'var(--text-2)')}</a>`).join('')}`;}
  else{const D=clansSorted();body=`<p class="sub">${_t("Classement mondial : {0} clans. Fin du mois dans {1} jour{2}. Le top 3 est récompensé chaque mois : trophée, tag doré pendant un mois, emblème en page d’accueil et cadres d’emblème exclusifs. Cagnotte mondiale : <b>{3}</b>, financée par {4} des frais générés par les clans, répartie entre les membres des 3 premiers au prorata de leurs points.",[D.length,monthLeft(),monthLeft()>1?'s':'',F.usd0(worldPot()),F.pct(CLAN.POT_SHARE*100)])}</p>${trH(D)}<p class="sub mt-4">${_t("Les divisions de {0} clans (montées, descentes et cagnotte par division) s’ouvriront à partir de {1} clans.",[CLAN.DIV_N,CLAN.DIV_MIN])}</p>`;}}
 else body=`<div class="clrules"><h3>${_t("Créer un clan")}</h3><p>${_t("Dès le rang {0} avec un compte de plus de {1} jours, {2} de frais non remboursables. Nom, tag de 3-4 lettres affiché partout à côté du pseudo, emblème, langues, catégories, description. {3} membres maximum.",[rankName(CLAN.MIN_TIER,0),CLAN.MIN_AGE_D,F.usd0(CLAN.FEE),CLAN.MAX])}</p><h3>${_t("Accès et rôles")}</h3><p>${_t("Ouvert (rang minimum réglable), sur candidature (rang minimum, validation par un officier) ou sur invitation. Un chef, jusqu’à {0} officiers (inviter, accepter, exclure, épingler), des membres. Chef inactif {1} jours : le clan passe à l’officier le plus actif. Quitter un clan : {2} jours d’attente avant d’en rejoindre un autre.",[CLAN.OFFICERS,CLAN.CHIEF_IDLE_D,CLAN.LEAVE_WAIT_D])}</p><h3>${_t("Classement mensuel")}</h3><p>${_t("XP de clan = volume misé par les membres sur le mois, plafonné à {0} par membre et par jour. Coefficient de forme = ROI du clan sur le mois (gain net / volume), borné entre ×0,5 et ×2. Score = XP × coefficient. Seuls les {1} meilleurs contributeurs comptent. Il faut {2} jours d’ancienneté dans le mois pour compter et être récompensé. Les mises entre deux membres du même clan sur le même marché ne donnent pas d’XP.",[F.usd0(CLAN.DAY_CAP),CLAN.TOP_CONTRIB,CLAN.MIN_DAYS])}</p><h3>${_t("Classement et divisions")}</h3><p>${_t("Tant qu’il y a moins de {0} clans, un seul classement mondial : le top 3 est récompensé chaque mois. À partir de {0} clans, des divisions de {1} clans, de la Division 5 à la Division 1, la plus haute. Chaque mois, les 3 premiers montent et les 3 derniers descendent. Chaque division a sa cagnotte, financée par {2} des frais générés par ses clans, répartie entre les membres au prorata de leurs points. Le top 3 mondial reçoit un trophée, un tag doré pendant un mois, l’emblème en page d’accueil et des cadres d’emblème exclusifs.",[CLAN.DIV_MIN,CLAN.DIV_N,F.pct(CLAN.POT_SHARE*100)])}</p><h3>${_t("Guerres de clans")}</h3><p>${_t("Le chef déclare la guerre ; matchmaking contre un clan de la même division ; {0} h. Chaque participant engage {1} dans la cagnotte de guerre. Score = points des 10 meilleurs de chaque camp. Le clan vainqueur prend la cagnotte, répartie entre ses participants.",[CLAN.WAR_H,F.usd0(CLAN.WAR_BUYIN)])}</p><h3>${_t("Séquestre et limites")}</h3><p>${_t("Pas de trésor de clan : toutes les cagnottes passent par le séquestre Wimoro, jamais par une personne. Les limites de jeu responsable priment sur tout : l’XP de clan n’incite jamais à les dépasser.")}</p></div>`;
 return `<div class="wrap clw">${hubSwH('clans')}<div class="pagehead"><div><h1 class="ptitle">${_t("Clans")}</h1><p class="plead">${_t("Un tag à côté de ton pseudo, un classement mensuel par division, des guerres de clans et une cagnotte partagée. Tout passe par le séquestre Wimoro.")}</p></div><div class="hbtns clh${mine?' has-mine':''}">${mine?`<a class="btn b-ink" href="#clan-${mine.id}">${_t("{0} Mon clan",[emblemH(mine,18)])}</a>`:`<button class="btn ${why?'b-white':'b-pri'}" data-a="cl-create-open" title="${esc(why)}">${_t("{0} Créer un clan",[ic('plus',16,why?'currentColor':'#fff')])}</button>`}</div></div>
 ${demoVu()?`<div class="clsim">${demoB()}<div class="seg">${[['few',_t('{0} clans',[12])+' · '+_t('classement mondial')],['many',_t('{0} clans',[100])+' · '+_t('divisions')]].map(([k,l])=>`<button class="${clanSim()===k?'on':''}" data-a="cl-sim" data-v="${k}">${l}</button>`).join('')}</div></div>`:''}
 <div class="g-side clg"><div class="col"><section class="pn pad clmain">${tabs}${body}</section></div>
 <aside class="col">${mine?`<section class="pn pad clg-1"><div class="h2">${_t("Mon clan")}</div>${clanRowH(mine)}<div class="sub mt-2">${_t("Ta contribution du mois : <b>{0}</b> de volume compté{1}.",[F.usd0(S.me.clanXP||0),memberCounts(mine,clanSince(mine))?'':` ${_t("· comptée après {0} jours d’ancienneté",[CLAN.MIN_DAYS])}`])}</div></section>`:rec?`<section class="pn pad clg-1"><div class="h2">${_t("Clan recommandé")}</div><p class="sub mt-1 mb-2">${_t("Selon ton rang et les catégories que tu joues.")}</p>${clanRowH(rec)}${clanEntrerH(rec,'b-ink full mt-3')}</section>`:''}
 ${mine?'':`<section class="pn pad"><div class="h2">${_t("Rejoindre avec un code")}</div><div class="sub">${_t("Un ami t’a envoyé le code de son clan ? Il ouvre aussi les clans sur invitation.")}</div><form class="col mt-3 gap-3" data-form="clcode"><div class="field"><input name="code" placeholder="WMR-XXXX" autocomplete="off" aria-label="${_t('Code d’invitation')}" class="upper"></div><button class="btn b-ink" type="submit">${_t("Rejoindre le clan")}</button><p class="err" data-clerr></p></form></section>`}
 ${why&&!mine?`<section class="pn pad"><div class="h2">${_t("Créer ton clan")}</div><p class="sub mt-2">${esc(why)}</p></section>`:''}</aside></div></div>`;}
function clanCreateModal(){const why=clanCanCreate();if(why){toast({tone:'amber',icon:'lock',title:_t("Création impossible"),text:why});return;}S.ui.clc=S.ui.clc||{name:'',tag:'',ic:'shield',col:'#2448FF',lang:['fr'],cats:[],desc:'',access:'open',minRank:0};
 openModal(`<div class="md"><div class="md-h"><div><p>${_t("Clan")}</p><h3>${_t("Créer un clan")}</h3></div><button class="x" data-a="close" aria-label="${_t("Fermer")}">${ic('x')}</button></div><form class="col" data-form="clan" novalidate>
 <div class="field"><label for="cln">${_t("Nom du clan")}</label><input id="cln" name="name" maxlength="28" placeholder="${_t("Les Loups du Volume")}" autocomplete="off"></div>
 <div class="field"><label for="clt">${_t("Tag (3 ou 4 lettres)")}</label><input id="clt" name="tag" maxlength="4" placeholder="LDV" autocomplete="off" class="upper"></div>
 <div class="cpf"><span class="cpl">${_t("Emblème")}</span><div class="chips">${CL_ICONS.map(i=>`<button type="button" class="chip${S.ui.clc.ic===i?' on':''}" data-a="clc-ic" data-v="${i}">${ic(i,14)}</button>`).join('')}</div><div class="ob-sw mt-2">${CL_COLS.map(c=>`<button type="button" class="${S.ui.clc.col===c?'on':''}" style="background:${c}" data-a="clc-col" data-v="${c}" aria-label="${_t("Couleur")}"></button>`).join('')}</div></div>
 <div class="cpf"><span class="cpl">${_t("Langues")}</span><div class="chips">${Object.keys(CL_LANGS).map(l=>`<button type="button" class="chip${S.ui.clc.lang.includes(l)?' on':''}" data-a="clc-lang" data-v="${l}">${CL_LANGS[l]}</button>`).join('')}</div></div>
 <div class="cpf"><span class="cpl">${_t("Catégories de prédilection")}</span><div class="chips">${CATS.filter(c=>c!=='Tout').map(c=>`<button type="button" class="chip${S.ui.clc.cats.includes(c)?' on':''}" data-a="clc-cat" data-v="${c}">${c}</button>`).join('')}</div></div>
 <div class="field"><label for="cld">${_t("Description")}</label><input id="cld" name="desc" maxlength="120" placeholder="${_t("Ce qu’on joue, quand on parle, l’ambiance.")}" autocomplete="off"></div>
 <div class="cpf"><span class="cpl">${_t("Accès")}</span><div class="chips">${[['open',_t("Ouvert")],['apply',_t("Sur candidature")],['invite',_t("Sur invitation")]].map(([k,l])=>`<button type="button" class="chip${S.ui.clc.access===k?' on':''}" data-a="clc-access" data-v="${k}">${l}</button>`).join('')}</div></div>
 <div class="field"><label for="clr">${_t("Rang minimum")}</label><select id="clr" name="minRank">${TIERS.slice(0,8).map((t,i)=>`<option value="${i}">${t.name}</option>`).join('')}</select></div>
 <div class="calc"><div class="line"><span>${_t("Frais de création, non remboursables")}</span><b>${F.usd0(CLAN.FEE)}</b></div></div>
 <div class="cpm-acts mt-4"><button class="btn b-pri lg" type="submit">${_t("{0} Créer le clan pour {1}",[ic('shield',16,'#fff'),F.usd0(CLAN.FEE)])}</button></div></form></div>`);}
function clanModalRefresh(){const o=$('#ov');if(!o)return;const name=$('#cln').value,tag=$('#clt').value,desc=$('#cld').value,mr=$('#clr').value;clanCreateModal();$('#cln').value=name;$('#clt').value=tag;$('#cld').value=desc;$('#clr').value=mr;}
FORMS.clcode=f=>{const code=f.code.value.trim().toUpperCase(),err=f.querySelector('[data-clerr]');if(!/^WMR-[A-Z0-9]{4}$/.test(code)){err.textContent=_t('Le code a la forme WMR-XXXX.');return;}const c=clanByCode(code);if(!c&&SRV()){srvClanRejoindre(null,true,code,err);return;}                 /* clan créé par un joueur : seul le serveur connaît son code */
 if(!c){err.textContent=_t('Code inconnu. Vérifie auprès de ton ami.');return;}if(!S.me.logged){needLogin(_t("Connecte-toi pour rejoindre un clan."));return;}if(clanJoin(c,false,true)){location.hash='#clan-'+c.id;}};
FORMS.clan=f=>{const st=S.ui.clc;const c=clanCreate({name:f.name.value,tag:f.tag.value,desc:f.desc.value,ic:st.ic,col:st.col,lang:st.lang,cats:st.cats,access:st.access,minRank:f.minRank.value});if(!c)return;closeModal();S.ui.clc=null;toast({tone:'green',icon:'shield',force:true,title:`${_t("{0} [{1}] est créé",[c.name,c.tag])}`,text:_t("Tu es le chef. Invite des membres et nomme jusqu’à 5 officiers."),href:'#clan-'+c.id});confetti(30);location.hash='#clan-'+c.id;};
/* les informations d'un clan (onglet Infos ; sur ordinateur, aussi dans la colonne latérale, carte « À propos ») */
function clanInfosH(c,mine){return `<div class="clinfo"><p>${esc(c.desc)}</p><div class="kvs"><div class="kv"><small>${_t("Langues")}</small><b>${c.lang.map(l=>CL_LANGS[l]||l).join(', ')}</b></div><div class="kv"><small>${_t("Catégories")}</small><b>${c.cats.map(x=>_t(x)).join(', ')}</b></div><div class="kv"><small>${_t("Accès")}</small><b>${c.access==='open'?_t("Ouvert"):c.access==='apply'?_t("Sur candidature"):_t("Sur invitation")}${c.minRank?`${_t(", dès {0}",[rankName(c.minRank,0)])}`:''}</b></div><div class="kv"><small>${_t("Créé")}</small><b>${new Date(c.createdAt).toLocaleDateString(LOC,{day:'numeric',month:'long',year:'numeric'})}</b></div><div class="kv"><small>${_t("Chef")}</small><b>${esc(duelUserN(c.chief))}</b></div><div class="kv"><small>${_t("Officiers")}</small><b>${c.officers.map(duelUserN).join(', ')||'—'}</b></div>${mine?`<div class="kv"><small>${_t("Code d’invitation")}</small><b class="num">${clanCode(c)}</b></div>`:''}</div></div>`;}
function vClan(id){const c=CK[id];if(!c)return vClans();clanChiefCheck(c);const mine=myClan()===c,role=mine?clanRole():'',tab=S.ui.cltab||(mine||c.feed.length||!clanMates(c).length?'activite':'membres'),   /* sans onglet choisi : le fil du clan, ou ses membres quand le fil est vide (clan dont on n'est pas membre) */mates=[...(mine?['me']:[]),...clanMates(c)],rid='clan:'+c.id;const rr=room(rid);rr.name=c.name;rr.kind='clan';rr.unread=0;if(!rr.msgs.length)clanSeedRoom(c);
 const pts=u=>u==='me'?Math.round((S.me.clanXP||0)):(c.members.find(m=>m.u===u)||{pts:0}).pts;const roleOf=u=>u===c.chief?_t("Chef"):c.officers.includes(u)?_t("Officier"):_t("Membre");
 let body='';
 if(tab==='activite')body=`<div class="clfeed">${c.feed.length?c.feed.map(e=>`<div class="clfe">${(e.u==='me'||USERS[e.u])?avH(e.u,24,'span'):''}<span>${esc(e.tk?_t(e.tk):e.txt)}<small>${ago(e.at)}</small></span></div>`).join(''):`<div class="empty">${_t("Pas encore d’activité. Les mises et victoires des membres (en opt-in) apparaîtront ici.")}</div>`}</div>${mine?`<label class="tgl mt-3"><input type="checkbox" data-a="cl-feedopt" ${S.me.prefs&&S.me.prefs.clanFeed===false?'':'checked'}><span class="sl"></span><span>${_t("Partager mes mises et mes gains dans le fil du clan")}</span></label>`:''}
  ${c.calls.length?`<div class="h2 mt-5">${_t("Appels de clan")}</div>${c.calls.map(k=>{const m=MK[k.m];return m?`<div class="clcall"><div>${_t("<b>{0}</b> · côté {1} · épinglé par {2}, {3}",[esc(m.short),k.s==='oui'?_t("Oui"):_t("Non"),esc(duelUserN(k.by)),ago(k.at)])}<small>${_t("{0} membre{1} suivi",[k.followers.length,k.followers.length>1?'s ont':' a'])}</small></div><button class="btn ${k.s==='oui'?'b-yes-soft':'b-no-soft'} sm" data-a="bet" data-m="${m.id}" data-s="${k.s}">${_t("Suivre à {0}",[F.c(k.s==='oui'?m.p:100-m.p)])}</button></div>`:'';}).join('')}`:''}
  ${mine&&isOfficer()?`<div class="hbtns mt-4"><button class="btn b-white sm" data-a="cl-call-open">${_t("{0} Appel de clan",[ic('target',14)])}</button></div>`:''}`;
 else if(tab==='semaine')body=clanWeekH(c);
 else if(tab==='chat')body=chatH(rid,'a-chat clchat',`<div class="chat-h"><div class="tt"><div><h2>${_t("Chat du clan")}</h2><div class="sub">${_t("{0} membres",[mates.length])}</div></div></div></div>`);
 else if(tab==='membres')body=`<div class="clmem">${mates.map(u=>`<div class="clmr"><span class="pl">${avH(u,32,'span')}<span><b>${esc(duelUserN(u))}</b><small>${_t("{0} · {1} pts{2}",[roleOf(u),F.int(pts(u)),u==='me'?(memberCounts(c,clanSince(c))?'':` ${_t("· compte dans {0} j",[Math.ceil(CLAN.MIN_DAYS-(now()-clanSince(c))/86400e3)])}`):''])}</small></span></span>${mine&&isOfficer()&&u!=='me'&&u!==c.chief?`<span class="hbtns">${role==='chef'&&!c.officers.includes(u)&&c.officers.length<CLAN.OFFICERS?`<button class="btn b-ghost sm" data-a="cl-promote" data-u="${u}">${_t("Nommer officier")}</button>`:''}<button class="btn b-ghost sm" data-a="cl-kick" data-u="${u}">${_t("Exclure")}</button></span>`:''}</div>`).join('')}</div>${mine&&isOfficer()?`<div class="hbtns mt-3"><button class="btn b-white sm" data-a="cl-invite">${_t("{0} Inviter un ami",[ic('userplus',14)])}</button></div>`:''}<p class="sub mt-3">${_t("Seuls les {0} meilleurs contributeurs comptent pour le score ; {1} jours d’ancienneté dans le mois pour compter et être récompensé.",[CLAN.TOP_CONTRIB,CLAN.MIN_DAYS])}</p>`;
 else if(tab==='positions')body=`<div class="pos-t clpos"><div class="ph2"><span>${_t("Membre")}</span><span>${_t("Marché")}</span><span>${_t("Côté")}</span><span class="r">${_t("Mise")}</span></div>${mates.flatMap(u=>u==='me'?S.me.positions.slice(0,3).map(p=>({u,m:MK[p.m],s:p.s,amt:p.sh*p.avg/100})):playerBets(u).slice(0,2).map(b=>({u,m:b.m,s:b.s,amt:b.amt}))).filter(x=>x.m).map(x=>`<div class="pr2"><span>${avH(x.u,22,'span')} ${esc(duelUserN(x.u))}</span><a href="#marche-${x.m.id}">${esc(x.m.short)}</a><span class="sidechip ${x.s}">${x.s==='oui'?_t("Oui"):_t("Non")}</span><span class="r num">${F.usd0(x.amt)}</span></div>`).join('')}</div>`;
 else if(tab==='guerre'){const w=c.war;const top=L=>L.slice().sort((a,b)=>b.pts-a.pts).slice(0,10);body=w?`<div class="clwar"><div class="clw-h"><b>${esc(c.name)} [${esc(c.tag)}]</b><span>${_t("contre")}</span><b>${esc(CK[w.foe].name)} [${esc(CK[w.foe].tag)}]</b></div><div class="bzkv"><div><small>${_t("Fin dans")}</small><b class="num">${Math.max(0,Math.round((w.endAt-now())/3600e3))} h</b></div><div><small>${_t("Cagnotte de guerre")}</small><b class="num">${F.usd0(w.pot)}</b>${_t("<em>séquestre Wimoro</em>")}</div><div><small>${_t("Score (10 meilleurs)")}</small><b class="num">${top(w.mine).reduce((t,x)=>t+x.pts,0)} – ${top(w.theirs).reduce((t,x)=>t+x.pts,0)}</b></div></div>${mine&&!w.mine.some(x=>x.u==='me')?`<button class="btn b-pri" data-a="cl-war-join">${_t("{0} Participer pour {1}",[ic('shield',16,'#fff'),F.usd0(w.buyin)])}</button>`:mine?`<div class="bzme ok">${_t("Tu participes : tes points suivent tes mises pendant la guerre.")}</div>`:''}<div class="clw-cols"><div>${_t("<b>Nos 10 meilleurs</b>{0}",[top(w.mine).map(x=>`<span>${esc(duelUserN(x.u))} <i>${x.pts}</i></span>`).join('')||`<span class="sub">${_t("Personne pour l’instant")}</span>`])}</div><div>${_t("<b>Leurs 10 meilleurs</b>{0}",[top(w.theirs).map(x=>`<span>${esc(duelUserN(x.u))} <i>${x.pts}</i></span>`).join('')])}</div></div></div>`:`<p class="sub">${_t("Aucune guerre en cours.{0}",[role==='chef'?_t(" En tant que chef, tu peux en déclarer une : matchmaking contre un clan de ta division, 48 h, buy-in par participant dans la cagnotte de guerre."):''])}</p>${role==='chef'?`<button class="btn b-ink" data-a="cl-war">${_t("{0} Déclarer la guerre",[ic('swords',16,'#fff')])}</button>`:''}`;body+=c.wars.length?`<div class="h2 mt-5">${_t("Guerres passées")}</div>${c.wars.map(w=>`<div class="bzh"><span>${fmtDT(w.at)}</span><span>${_t("contre {0}",[esc(CK[w.foe].name)])}</span><span>${w.status==='won'?_t("Gagnée"):w.status==='lost'?_t("Perdue"):_t("Égalité")} ${w.a} – ${w.b}, ${F.usd0(w.pot)}</span></div>`).join('')}`:'';}
 else body=clanInfosH(c,mine);
 /* entrer dans le clan : l'action principale de la page pour un joueur connecté qui n'en est pas membre (un seul bouton
    bleu ; pour un visiteur, le bouton bleu reste « S'inscrire », dans l'en-tête) */
 const pri=S.me.logged?'b-pri':'b-ink';
 const act=mine?`<button class="btn b-white" data-a="copy" data-v="${clanCode(c)}" title="${_t('Code d’invitation')}">${ic('copy',16)} <span class="num">${clanCode(c)}</span></button><button class="btn b-white" data-a="cl-share">${_t("{0} Récap hebdo",[ic('share',16)])}</button><button class="btn b-ghost cl-leave-h" data-a="cl-leave">${_t("Quitter le clan")}</button>`:c.access==='open'?`<button class="btn ${pri}" data-a="cl-join" data-id="${c.id}">${_t("{0} Rejoindre",[ic('shield',16,'#fff')])}</button>`:c.access==='apply'?(S.me.clanApps&&S.me.clanApps[c.id]?`<span class="btn b-ghost" disabled>${_t("Candidature envoyée")}</span>`:`<button class="btn ${pri}" data-a="cl-apply" data-id="${c.id}">${_t("{0} Candidater",[ic('send',16,'#fff')])}</button>`):`<span class="btn b-ghost" disabled>${_t("{0} Sur invitation",[ic('lock',16)])}</span>`;
 return `<div class="wrap clpw"><div class="pagehead clph"><div><nav class="crumbs"><a href="#clans">${_t("Clans")}</a><span>/</span><span>${esc(c.name)}</span></nav><div class="clhead">${emblemH(c,56)}<div><h1 class="ptitle">${esc(c.name)} <span class="ctg${clanWorldRank(c)<=3?' gold':''} t-3">${esc(c.tag)}</span></h1><p class="plead mt-1">${_t("{0} · {1} points ce mois · {2} membre{3} sur {4}{5}",[clanPosTxt(c),F.int(c.score),clanMembersN(c),clanMembersN(c)>1?'s':'',CLAN.MAX,clanWorldRank(c)<=3?` ${_t("· {0} top {1} mondial",[ic('trophy',14,'var(--text-2)'),clanWorldRank(c)])}`:''])}</p></div></div></div><div class="hbtns">${act}</div></div>
 <div class="g-side"><div class="col"><section class="pn pad"><div class="tabs utabs ctabs">${[['activite',_t("Activité")],['semaine',_t('Semaine')],['chat',_t("Chat")],['membres',_t("Membres")],['positions',_t("Positions")],['guerre',_t("Guerre")],['infos',_t("Infos")]].map(([k,l])=>`<button class="${tab===k?'on':''}" data-a="cl-ctab" data-v="${k}">${l}</button>`).join('')}</div>${body}${tab==='infos'&&mine?`<div class="cl-leave-m"><button class="link" data-a="cl-leave">${_t("Quitter le clan")}</button></div>`:''}</section></div>
 <aside class="col"><section class="pn pad"><div class="h2">${_t("Score du mois")}</div><div class="bzkv mt-2"><div><small>${_t("XP de clan")}</small><b class="num">${F.int(c.xp)}</b>${_t("<em>volume plafonné</em>")}</div><div><small>${_t("Coefficient")}</small><b class="num">${clanCoef(c)}</b><em>ROI ${pctFx(c.roi*100)}</em></div><div><small>${_t("Score")}</small><b class="num">${F.int(c.score)}</b><em>${clanDivMode()?`${_t("{0} de {1}",[ordinal(c.rank),divName(c)])}`:`${_t("{0} mondial",[ordinal(clanWorldRank(c))])}`}</em></div></div><p class="sub">${_t("Score = XP × coefficient. {0} meilleurs contributeurs, {1} jours d’ancienneté, mises entre membres exclues. {2}",[CLAN.TOP_CONTRIB,CLAN.MIN_DAYS,clanDivMode()?`${_t("Cagnotte de la division : {0}.",[F.usd0(divPot(c.div))])}`:`${_t("Cagnotte mondiale : {0}.",[F.usd0(worldPot())])}`])}</p></section>
 ${mine?`<section class="pn pad"><div class="h2">${_t("Ta contribution")}</div><div class="bzkv mt-2"><div><small>${_t("Ce mois")}</small><b class="num">${F.usd0(S.me.clanXP||0)}</b></div><div><small>${_t("Aujourd’hui")}</small><b class="num">${F.usd0(clanVolToday())}</b>${_t("<em>plafond {0}</em>",[F.usd0(CLAN.DAY_CAP)])}</div><div><small>${_t("Rôle")}</small><b>${role==='chef'?_t("Chef"):role==='officier'?_t("Officier"):_t("Membre")}</b></div></div>${S.me.clanSkipped?`<p class="sub">${_t("{0} mise{1} non comptée{1} : même marché qu’un membre du clan.",[S.me.clanSkipped,S.me.clanSkipped>1?'s':''])}</p>`:''}</section>`:''}
 ${GRAND()&&tab!=='infos'?`<section class="pn pad clabout"><div class="h2">${_t("À propos")}</div>${clanInfosH(c,mine)}</section>`:''}</aside></div></div>`;}
/* les trois messages d'accueil d'un salon de clan ; en mode Compte, c'est le serveur qui les pose (gabarit « C »), une fois pour tous les membres */
const CLAN_ACCUEIL=[()=>_t("Qui prend le Clásico ce soir ?"),()=>_t("Je suis Oui sur #btc150k à 63, on monte."),()=>_t("Appel de clan ce soir à 21 h, soyez là.")];
function clanSeedRoom(c){if(SRV())return;const t=now(),ids=clanMates(c).length?clanMates(c):USER_IDS.slice(0,3);CLAN_ACCUEIL.forEach((x,i)=>addMsg('clan:'+c.id,mkMsg({u:ids[i%ids.length],k:'msg',text:x(),at:t-(12-i*4)*60000})));}
function clanCallModal(){const c=myClan();if(!c||!isOfficer())return;openModal(`<div class="md"><div class="md-h"><div><p>${_t("Appel de clan")}</p><h3>${_t("Épingler un marché")}</h3></div><button class="x" data-a="close" aria-label="${_t("Fermer")}">${ic('x')}</button></div><p class="sub">${_t("Les membres le voient en tête du fil et suivent en un tap, chacun avec sa mise et dans ses propres limites.")}</p><div class="field"><label for="clcm">${_t("Marché")}</label><select id="clcm">${MARKETS.filter(m=>!m.creator).map(m=>`<option value="${m.id}">${esc(m.short)}</option>`).join('')}</select></div><div class="sides mt-3 mb-3"><button type="button" class="sd oui on" data-clcs="oui"><span>${_t("Oui")}</span></button><button type="button" class="sd non" data-clcs="non"><span>${_t("Non")}</span></button></div><div class="cpm-acts"><button class="btn b-ink lg" data-a="cl-call-do">${_t("{0} Lancer l’appel",[ic('target',16,'#fff')])}</button></div></div>`);}
/* fil : mes gains (opt-in) */
function clanOnWin(txt){const c=myClan();if(!c||(S.me.prefs&&S.me.prefs.clanFeed===false))return;clanFeedPush(c,{u:'me',txt});}
/* accueil : le top clan mondial a son emblème en page d'accueil */
const nf3c=new Intl.NumberFormat(LOC,{minimumFractionDigits:3,maximumFractionDigits:3});const clanCoef=c=>bidi('×'+NB(nf3c.format(c.coef)));
/* ---------- Version 20 : le clan mis en avant ---------- */
/* CL4, CL5 : ce qu'une mise compterait pour le clan. Même calcul que clanRecordBet, sans rien écrire. */
function clanCount(mid,amt){const c=myClan();if(!c||!(amt>0))return null;const late=!memberCounts(c,clanSince(c));if(mid&&clanMates(c).some(u=>playerBets(u).some(b=>b.m.id===mid)))return {c,add:0,why:'mate',late};
 const cur=(S.me.clanVol||{})[today()]||0,add=Math.max(0,Math.min(CLAN.DAY_CAP-cur,amt));return {c,add,why:add<=0?'cap':add<amt-1e-9?'partial':'',late};}
const clanAmt=v=>bidi('+'+plain(Math.abs(v-Math.round(v))<.005?F.usd0(v):F.usd(v)));
function clanToastTxt(x){return x&&x.add>0?(x.late?_t('{0} pour {1}',[clanAmt(x.add),x.c.name]):_t('{0} comptés pour {1}',[clanAmt(x.add),x.c.name])):'';}
function clanTicketIn(mid,amt){const c=myClan();if(!c)return '';const x=clanCount(mid,amt)||{c,add:0,why:'',late:!memberCounts(c,clanSince(c))},n=esc(c.name);
 const lab=x.why==='mate'?_t('{0} : un membre a déjà misé ici',[n]):x.why==='cap'?_t('{0} : plafond du jour atteint',[n]):x.late?_t('Contribution à {0} (dès {1} jours d’ancienneté)',[n,CLAN.MIN_DAYS]):x.why==='partial'?_t('Contribution à {0} (plafond du jour)',[n]):_t('Contribution à {0}',[n]);
 return `<span class="tcl-l">${emblemH(c,16)}<span>${lab}</span></span><b>${clanAmt(x.add)}</b>`;}
