function clanWarBarH(cls){const c=myClan(),w=c&&c.war;if(!w||w.status!=='live'||!CK[w.foe])return '';const sc=L=>L.slice().sort((a,b)=>b.pts-a.pts).slice(0,10).reduce((t,x)=>t+x.pts,0),foe=CK[w.foe],hh=Math.max(0,Math.round((w.endAt-now())/3600e3));
 return `<a class="clwarbar${cls?' '+cls:''}" href="#clan-${c.id}" data-a="cl-war-open">${ic('swords',15)}<b class="cwb-t">${_t("Guerre de clans")}</b><span class="cwb-s" dir="ltr"><b>${esc(c.tag)}</b> <span class="num">${F.int(sc(w.mine))} – ${F.int(sc(w.theirs))}</span> <b>${esc(foe.tag)}</b></span><span class="cwb-e">${_t('fin dans {0} h',[hh])}</span>${ic('chev',14)}</a>`;}
