const placeBet0=placeBet;placeBet=function(ctx,ev){const st=tState(ctx),c=calcT(st),before=S.me.balance;placeBet0(ctx,ev);if(S.me.balance<before-1e-6&&c&&c.amt)clanRecordBet(st.m,c.amt);};
const flashBet0=flashBet;flashBet=function(side,ev,gid){const before=S.me.balance;flashBet0(side,ev,gid);if(S.me.balance<before-1e-6){const x=clanCount(null,before-S.me.balance);clanRecordBet(null,before-S.me.balance);if(x&&x.add>0){CLAN_FL[S.flash.round+':'+(GM[gid||S.ui.fgame]||GAMES[0]).id]=x;if(typeof updateFlash==='function')updateFlash(true);}}};
